mapper.select:
SELECT id, message_id, recalled_at FROM im_direct_recall
WHERE user_low_id = #{low} AND user_high_id = #{high} AND id > #{afterId}
ORDER BY id ASC LIMIT #{limit}

SELECT id, sender_id, recipient_id, client_msg_id, body, created_at, recalled_at
FROM im_direct_message
WHERE user_low_id = #{low} AND user_high_id = #{high}
AND id < #{beforeId}
ORDER BY id DESC
LIMIT #{limit}

SELECT id, sender_id, recipient_id, client_msg_id, body, created_at, recalled_at
FROM im_direct_message FORCE INDEX (idx_direct_pair_history)
WHERE user_low_id = #{low} AND user_high_id = #{high} AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}

SELECT id, sender_id, recipient_id, client_msg_id, body, created_at, recalled_at
FROM im_direct_message FORCE INDEX (idx_direct_pair_history)
WHERE user_low_id = #{low} AND user_high_id = #{high}
  AND recalled_at IS NULL AND body LIKE CONCAT('%', #{pattern}, '%') ESCAPE '='
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}
